class ServiceError(Exception):
    def __init__(self, status):
        self.status = status


class FakeClient:
    def __init__(self, script):
        self.script = list(script)
        self.calls = 0

    def call(self):
        self.calls += 1
        outcome = self.script.pop(0)
        if outcome == "ok":
            return "ok"
        raise ServiceError(int(outcome))


RETRYABLE = {500, 502, 503}


def fetch(client, attempts):
    for n in range(1, attempts + 1):
        try:
            return client.call()
        except ServiceError as err:
            print("attempt %d failed with %d" % (n, err.status))
            if err.status not in RETRYABLE:
                return "stopped"
    return "gave up"


client = FakeClient(["503", "404", "ok"])
print(fetch(client, 4), client.calls)
